effect.shader:
// Cosine Web (Zozuar 2) - AM single pass, GLES-safe loops

mat2 rotate2D(float r){ return mat2(cos(r), sin(r), -sin(r), cos(r)); }

void main(){
    vec2 R = acScreenSize;
    vec2 uv = (acScreenNorm * R - 0.5 * R) / max(R.y, 1.0);
    vec3 col = vec3(0.0);
    float t = acTime * TIME_SPEED;

    vec2 n = vec2(0.0), q;
    vec2 N = vec2(0.0);
    vec2 p = uv + t / 10.0;
    float S = S0;
    mat2 m = rotate2D(ROT);

    int iters = int(clamp(ITER, 1.0, 64.0));
    const int MAX_IT = 64;
    for (int j = 0; j < MAX_IT; ++j){
        if (j >= iters) break;
        p = m * p;
        n = m * n;
        q = p * S + float(j) + n + t;
        n += sin(q);
        N += cos(q) / S;
        S *= S_GROW;
    }

    vec3 cm = COLOR_MUL.rgb; // default ~ vec3(1,2,4)
    float invLen = (length(N) > 1e-6) ? (DETAIL / length(N)) : 0.0;
    col = cm * ((N.x + N.y + ADD_BIAS) + invLen);

    col = pow(max(col, 0.0), vec3(GAMMA));
    gl_FragColor = vec4(col, 1.0);
}
